import {TYPES,FABRICS,COLORS,CAMPAIGNS,EVENTS,money,defaultDesign,freshGame,unitCost,placeOrder,forecast,launch,outcome,validSave} from './engine.js';
const $=s=>document.querySelector(s), key='fashion-world-save-v1';
let state,saveWarning=false;try{const raw=JSON.parse(localStorage.getItem(key));state=validSave(raw)?raw:freshGame('Maison Nova');}catch{state=freshGame('Maison Nova');saveWarning=true;}
let design=defaultDesign(),campaign='organic',choice=0,tab='studio',sound=false;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const type=id=>TYPES.find(t=>t.id===id),fabric=id=>FABRICS.find(t=>t.id===id),color=id=>COLORS.find(t=>t.id===id);
const event=()=>EVENTS[Math.min(state.week-1,11)];
const inStock=()=>state.inventory.reduce((a,i)=>a+i.remaining,0);
const persist=()=>{try{localStorage.setItem(key,JSON.stringify(state));}catch{saveWarning=true;}};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function ping(){if(!sound)return;try{const audio=new (window.AudioContext||window.webkitAudioContext)();[523,659,784].forEach((f,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=f;g.gain.setValueAtTime(.035,audio.currentTime+i*.075);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.3+i*.075);o.start(audio.currentTime+i*.075);o.stop(audio.currentTime+.35+i*.075);});setTimeout(()=>audio.close(),900);}catch{}}
function photo(id,extra=''){return `<div class="garment-photo ${extra}" style="--photo-position:${type(id).image*50}%" role="img" aria-label="Editorial reference: ${escape(type(id).name)}"></div>`;}
function showModal(html){const modal=$('#modal');modal.innerHTML=html;if(!modal.open)modal.showModal();}
function closeModal(){$('#modal').close();}
function header(){return `<header class="topbar"><a class="brand" href="./" aria-label="Fashion World home">fashion<span>world</span><sup>®</sup></a><div class="season-label">THE INDEPENDENT LABEL GAME</div><div class="header-actions"><button class="icon-button" data-action="sound" aria-label="${sound?'Mute':'Enable'} sound">${sound?'Sound on':'Sound off'}</button><button class="help-button" data-action="help">How to play <span>?</span></button></div></header><div class="shell"><aside class="sidebar"><div class="studio-label">YOUR FASHION HOUSE</div><button class="label-name" data-action="rename">${escape(state.label)} <span>↗</span></button><div class="sidebar-rule"></div><nav aria-label="Game sections">${[['studio','01','Design studio'],['collection','02','Your collection'],['ledger','03','The books'],['season','04','Season goals']].map(([id,n,name])=>`<button data-tab="${id}" class="nav-button ${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}><span>${n}</span>${name}${id==='collection'?`<b>${inStock()}</b>`:''}</button>`).join('')}</nav><div class="season-card"><span class="eyebrow">YOUR FIRST SEASON</span><strong>${state.finished?'Finale':`Week ${state.week}`} <small>/ 12</small></strong><div class="progress-track"><i style="width:${Math.min(100,(state.week-1)/12*100)}%"></i></div><p>Start small.<br>Make something matter.</p></div><button class="new-season" data-action="restart">↻ &nbsp; New season</button><div class="save-status">${saveWarning?'Saving unavailable in this browser':'Progress saved on this device'}</div></aside><main><div class="dashboard-top"><div><span class="eyebrow">${state.finished?'SEASON COMPLETE':`WEEK ${String(state.week).padStart(2,'0')} · YOUR NEXT CHAPTER`}</span><h1>${{studio:'The design studio.',collection:'Made by you.',ledger:'Behind the label.',season:'Make your mark.'}[tab]}</h1></div><div class="season-pill"><span></span>${state.finished?'Season complete':'Season 01'}</div></div><section class="stats" aria-label="Your label’s performance">${[['Available cash',money(state.cash),'Started with $8,000'],['Followers',state.followers.toLocaleString(),'Your growing community'],['Reputation',`${state.reputation}<small>/100</small>`,'Your name in the industry'],['Total sales',money(state.revenue),`${state.unitsSold} pieces sold`]].map(([label,value,note])=>`<div class="stat"><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`).join('')}</section>${state.finished?endBanner():''}`;}
function endBanner(){const o=outcome(state);return `<section class="end-banner"><div><span class="eyebrow">${o.rank}</span><h2>${o.title}</h2><p>${o.text}</p></div><button class="primary" data-action="results">View your results ↗</button></section>`;}
function studio(){const e=event(),t=type(design.type),f=fabric(design.fabric),cost=unitCost(design),estimate=Math.round(forecast(state,design,campaign,choice)),bill=CAMPAIGNS.find(c=>c.id===campaign).cost+e.choices[choice].cost+250;return `<section class="market-strip"><span class="market-icon">✦</span><div><span class="eyebrow">THE MARKET MOOD</span><p>${e.text}</p></div><div class="trend-pills"><span>↗ ${type(e.type).short}</span><span><i style="background:${color(e.color).hex}"></i>${color(e.color).name}</span></div></section><div class="studio-grid"><section class="design-panel panel"><div class="panel-heading"><div><span class="eyebrow">01 / CREATE</span><h2>Build your next piece</h2></div><span class="little-tag">${state.ordersThisWeek}/3 designs</span></div><div class="design-body"><div class="preview"><div class="preview-top"><span>STUDIO REFERENCE</span><span>FW—0${t.image+1}</span></div>${photo(design.type)}<div class="preview-caption"><div><span>${t.style.toUpperCase()}</span><h3>${t.name}</h3></div><span class="fabric-tag">${f.name}</span></div><div class="sample-note">Silhouette reference · your color and fabric affect gameplay.</div></div><div class="design-controls"><label class="field-title" for="piece">The silhouette</label><div class="segmented" id="piece">${TYPES.map(t=>`<button class="${design.type===t.id?'selected':''}" data-type="${t.id}" aria-pressed="${design.type===t.id}">${t.short}</button>`).join('')}</div><label class="field-title" for="fabric">The fabric</label><select id="fabric" ${state.finished?'disabled':''}>${FABRICS.map(f=>`<option value="${f.id}" ${design.fabric===f.id?'selected':''}>${f.name} ${f.extra?`(+$${f.extra}/piece)`:''}</option>`).join('')}</select><p class="field-note">${f.description}</p><span class="field-title">The colorway <small>${color(design.color).name}</small></span><div class="swatches">${COLORS.map(c=>`<button class="swatch ${design.color===c.id?'selected':''}" data-color="${c.id}" style="--swatch:${c.hex}" aria-label="${c.name}" aria-pressed="${design.color===c.id}">${design.color===c.id?'✓':''}</button>`).join('')}</div><div class="input-pair"><div><label class="field-title" for="quantity">Production quantity</label><div class="number-field"><input id="quantity" type="number" min="10" max="150" step="1" value="${design.quantity}" inputmode="numeric"><span>pieces</span></div></div><div><label class="field-title" for="price">Retail price</label><div class="number-field"><span>$</span><input id="price" type="number" min="25" max="250" step="1" value="${design.price}" inputmode="numeric"></div></div></div><div class="cost-breakdown"><div><span>Cost per piece</span><b>${money(cost)}</b></div><div><span>Gross margin per sale</span><b class="${design.price<cost?'negative':''}">${money(design.price-cost)}</b></div><div><span>Production total</span><b>${money(cost*design.quantity)}</b></div></div><button class="primary wide" data-action="produce" ${state.finished||state.ordersThisWeek>=3?'disabled':''}>Produce this design <span>↗</span></button><p class="forecast">About ${Math.round(estimate*.75)}–${Math.round(estimate*1.2)} potential buyers before competition between your pieces. Estimates aren’t guarantees.</p></div></div></section><aside class="week-panel"><section class="event-card"><span class="eyebrow">02 / MAKE YOUR MOVE</span><div class="event-title"><h2>${e.title}</h2><span>✧</span></div><p>Choose how your label shows up this week.</p><div class="event-choices">${e.choices.map((c,i)=>`<button class="event-choice ${choice===i?'chosen':''}" data-choice="${i}" aria-pressed="${choice===i}"><span class="radio-dot"></span><span><b>${c.name}</b><small>${c.description}</small></span></button>`).join('')}</div></section><section class="campaign-card panel"><span class="eyebrow">03 / GET SEEN</span><h2>Give it a moment</h2><label class="sr-only" for="campaign">Marketing campaign</label><select id="campaign">${CAMPAIGNS.map(c=>`<option value="${c.id}" ${campaign===c.id?'selected':''}>${c.name} · ${money(c.cost)}</option>`).join('')}</select><p class="field-note">${CAMPAIGNS.find(c=>c.id===campaign).description}</p><div class="launch-summary"><div><span>Ready to sell</span><b>${inStock()} pieces</b></div><div><span>Studio overhead</span><b>$250</b></div><div><span>Event + marketing</span><b>${money(bill-250)}</b></div></div><button class="launch-button wide" data-action="launch" ${state.finished?'disabled':''}>Launch week ${Math.min(state.week,12)} <span>→</span></button><p class="launch-note">${money(bill)} due at launch. Advances one week.</p></section></aside></div><div class="bottom-note"><span>THE FOUNDER’S NOTE</span><p>Good taste gets attention. Good decisions keep the studio open.</p><button data-action="help">Learn the rules ↗</button></div>`;}
function collection(){return `<div class="section-intro"><p>Every piece you’ve made. Unsold inventory stays available for your next launch.</p><button class="text-button" data-tab="studio">Back to the studio ↗</button></div>${state.inventory.length?`<div class="collection-grid">${state.inventory.map(i=>`<article class="collection-card panel">${photo(i.type)}<div class="collection-details"><div class="eyebrow">WEEK ${i.created} · ${fabric(i.fabric).name}</div><h2>${type(i.type).name}</h2><p><span class="color-dot" style="background:${color(i.color).hex}"></span>${color(i.color).name} · ${money(i.price)} retail</p><div class="inventory-numbers"><span><b>${i.remaining}</b> in stock</span><span><b>${i.sold}</b> sold</span></div>${i.remaining&&!state.finished?`<label class="field-title" for="repr-${i.id}">Update retail price</label><div class="reprice"><input id="repr-${i.id}" type="number" min="25" max="250" value="${i.price}" aria-label="New price for ${type(i.type).name}"><button data-reprice="${i.id}">Save price</button></div>`:`<span class="little-tag">${i.remaining?'Season archive':'Sold out'}</span>`}</div></article>`).join('')}</div>`:`<div class="empty-state"><span>✧</span><h2>Your first piece starts here.</h2><p>Choose a silhouette, fabric, and colorway in the studio, then place your first production order.</p><button class="primary" data-tab="studio">Design your first piece ↗</button></div>`}`;}
function ledger(){const totalProfit=state.history.reduce((n,h)=>n+h.profit,0),stockValue=state.inventory.reduce((n,i)=>n+i.remaining*i.cost,0);return `<div class="ledger-highlights"><div><span>Operating profit</span><strong>${money(totalProfit)}</strong></div><div><span>Inventory at cost</span><strong>${money(stockValue)}</strong></div><div><span>Cash + inventory</span><strong>${money(state.cash+stockValue)}</strong></div></div><p class="section-intro">Profit subtracts the cost of pieces sold and weekly expenses. Cash also reflects production paid upfront.</p>${state.history.length?`<div class="panel ledger-table"><table><caption class="sr-only">Weekly financial results</caption><thead><tr><th>Week</th><th>Pieces sold</th><th>Revenue</th><th>Production paid</th><th>Other costs</th><th>Profit</th><th>Closing cash</th></tr></thead><tbody>${state.history.map(h=>`<tr><td><b>${String(h.week).padStart(2,'0')}</b></td><td>${h.sold}</td><td>${money(h.revenue)}</td><td>${money(h.production)}</td><td>${money(h.expenses)}</td><td class="${h.profit<0?'negative':'positive'}">${money(h.profit)}</td><td>${money(h.cash)}</td></tr>`).join('')}</tbody></table></div><section class="panel sales-chart"><h2>Your sales story</h2><div class="bars" role="img" aria-label="Weekly revenue bar chart">${state.history.map(h=>`<div class="bar-column"><small>${money(h.revenue)}</small><div class="bar" style="height:${Math.max(3,h.revenue/Math.max(...state.history.map(x=>x.revenue),1)*140)}px"></div><span>W${h.week}</span></div>`).join('')}</div></section>`:`<div class="empty-state"><h2>The books are open.</h2><p>Launch your first week to see your sales, costs, and profit here.</p></div>`}`;}
function season(){return `<div class="section-intro"><p>Twelve weeks to find your audience. How far can you take your label?</p></div><div class="goals-grid">${[['Stay in the game','Finish all 12 weeks with your studio open.',Math.min(state.history.length,12),12,'weeks'],['Build an independent success','Finish with at least $12,000 in cash.',state.cash,12000,'cash'],['Become a breakout label','Reach $20,000 in cash and 65 reputation.',Math.min(state.cash/20000,state.reputation/65)*100,100,'percent']].map(([title,desc,value,target,format],idx)=>`<section class="goal-card panel"><span class="goal-index">0${idx+1}</span><h2>${title}</h2><p>${desc}</p><div class="progress-track"><i style="width:${Math.min(100,value/target*100)}%"></i></div><b>${format==='cash'?money(value):Math.floor(value)}${format==='percent'?'%':` / ${format==='cash'?money(target):target+' weeks'}`}</b></section>`).join('')}</div><section class="panel season-guide"><span class="eyebrow">A FEW THINGS TO REMEMBER</span><h2>You’re building a business with a point of view.</h2><div><p><b>Follow the mood.</b> Trending silhouettes and colors attract more shoppers. Premium materials can support higher prices.</p><p><b>Know your limits.</b> Production is paid upfront. Save enough for $250 in weekly overhead, plus any marketing or events.</p><p><b>Keep stock moving.</b> Too many designs split your audience. Adjust old prices in Your collection before you launch.</p></div></section>`;}
function render(){const focused=document.activeElement?.id;$('#app').innerHTML=header()+({studio,collection,ledger,season}[tab])()+`<footer><span>FASHION WORLD</span><span>A little ambition. A world of possibilities.</span></footer></main></div>`;if(focused)document.getElementById(focused)?.focus();}
function help(){showModal(`<div class="modal-heading"><span class="eyebrow">WELCOME TO FASHION WORLD</span><button data-action="close" aria-label="Close">×</button></div><h2>Your label. Your rules.</h2><p>You have <b>$8,000, 250 followers, and 12 weeks</b> to build a fashion business.</p><ol class="help-list"><li><b>Create a piece.</b> Pick a silhouette, fabric, color, price, and quantity. Producing deducts the full cost immediately.</li><li><b>Read the room.</b> Follow market trends and choose an event response. Each choice shows its cost and benefit.</li><li><b>Launch your week.</b> Choose marketing, then launch. Shoppers buy from all available inventory. Every week costs $250 to run.</li><li><b>Build on what works.</b> Unsold stock carries forward. Change its price in Your collection. View your numbers in The books.</li></ol><p class="help-tip">Try 30 organic-cotton polos at $68 for your first drop. Keep a cash buffer. Reach $12,000 for an independent success, or $20,000 and 65 reputation for a breakout.</p><p class="field-note">This is a fictional business simulation. Progress saves in this browser only. No purchases or real money.</p><button class="primary wide" data-action="close">Let’s make something ↗</button>`);}
function reportModal(r){showModal(`<div class="modal-heading"><span class="eyebrow">WEEK ${r.week} / THE RESULTS</span><button data-action="close" aria-label="Close results">×</button></div><h2>${r.sold?'Your drop is out there.':'A quiet week in the studio.'}</h2><p>${r.event} · ${r.campaign}</p><div class="report-numbers"><div><strong>${money(r.revenue)}</strong><span>Revenue</span></div><div><strong>${r.sold}</strong><span>Pieces sold</span></div><div><strong class="${r.profit<0?'negative':''}">${money(r.profit)}</strong><span>Operating profit</span></div></div><div class="report-lines">${r.lines.length?r.lines.map(l=>`<div><span>${type(l.type).short} · ${color(l.color).name}</span><b>${l.sold} sold / ${l.remaining} left</b></div>`).join(''):'<p>No inventory was available. Produce a design before your next launch.</p>'}</div><p class="help-tip">${r.sold===0?'Try a more accessible price or a smaller collection that follows the market mood.':inStock()===0?'You sold out. Consider a slightly larger order next week, while leaving room for operating costs.':'Your remaining stock will be available next week. You can adjust its price in Your collection.'}</p><button class="primary wide" data-action="${state.finished?'results':'close'}">${state.finished?'See your season results':'On to the next week'} →</button>`);}
function results(){const o=outcome(state);showModal(`<div class="modal-heading"><span class="eyebrow">${o.rank.toUpperCase()}</span><button data-action="close" aria-label="Close">×</button></div><div class="result-star">✦</div><h2>${o.title}</h2><p>${o.text}</p><div class="report-numbers"><div><strong>${money(state.cash)}</strong><span>Final cash</span></div><div><strong>${state.followers}</strong><span>Followers</span></div><div><strong>${state.reputation}</strong><span>Reputation</span></div></div><p class="field-note">${state.unitsSold} pieces sold · ${money(state.revenue)} revenue · ${inStock()} pieces in the archive</p><button class="primary wide" data-action="restart">Create a new season ↗</button><button class="text-button wide" data-action="close">Explore your final numbers</button>`);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.tab){tab=b.dataset.tab;render();return;}if(b.dataset.type){design.type=b.dataset.type;design.price=type(design.type).value;render();return;}if(b.dataset.color){design.color=b.dataset.color;render();return;}if(b.dataset.choice!==undefined){choice=Number(b.dataset.choice);render();return;}if(b.dataset.reprice){const price=Number(document.getElementById(`repr-${b.dataset.reprice}`).value);if(!Number.isInteger(price)||price<25||price>250)throw Error('Set a whole-dollar price between $25 and $250.');const item=state.inventory.find(i=>i.id===b.dataset.reprice);item.price=price;persist();render();toast('New price saved for your next launch.');return;}switch(b.dataset.action){case'help':help();break;case'close':closeModal();break;case'sound':sound=!sound;render();ping();break;case'produce':state=placeOrder(state,design);persist();render();ping();toast(`${design.quantity} ${type(design.type).short.toLowerCase()} pieces added to your collection.`);break;case'launch':if(!inStock()){showModal(`<div class="modal-heading"><span class="eyebrow">NO STOCK TO SELL</span><button data-action="close" aria-label="Close">×</button></div><h2>Take a quiet week?</h2><p>You have no stock. Advancing will still charge overhead, event, and marketing costs.</p><button class="primary wide" data-action="launch-confirmed">Advance without stock</button><button class="text-button wide" data-action="close">Back to designing</button>`);break;}advance();break;case'launch-confirmed':advance();break;case'results':results();break;case'rename':showModal(`<div class="modal-heading"><span class="eyebrow">MAKE IT YOURS</span><button data-action="close" aria-label="Close">×</button></div><h2>Name your label.</h2><form id="rename-form"><label class="field-title" for="label-input">Fashion house name</label><input id="label-input" maxlength="32" value="${escape(state.label)}" required autofocus><button class="primary wide" type="submit">Save your label ↗</button></form>`);break;case'restart':showModal(`<div class="modal-heading"><span class="eyebrow">A FRESH START</span><button data-action="close" aria-label="Close">×</button></div><h2>Start a new season?</h2><p>This replaces your current saved season. You’ll begin again with $8,000 and 250 followers.</p><button class="primary wide" data-action="reset-confirmed">Start a new season</button><button class="text-button wide" data-action="close">Keep this season</button>`);break;case'reset-confirmed':state=freshGame(state.label);design=defaultDesign();campaign='organic';choice=0;tab='studio';persist();closeModal();render();toast('A fresh season. A world of possibilities.');break;}}catch(error){toast(error.message);}});
function advance(){const result=launch(state,campaign,choice);state=result.state;persist();choice=0;campaign='organic';render();ping();reportModal(result.report);}
document.addEventListener('change',e=>{if(e.target.id==='fabric')design.fabric=e.target.value;else if(e.target.id==='quantity')design.quantity=Math.max(10,Math.min(150,Math.round(Number(e.target.value)||10)));else if(e.target.id==='price')design.price=Math.max(25,Math.min(250,Math.round(Number(e.target.value)||25)));else if(e.target.id==='campaign')campaign=e.target.value;else return;render();});
document.addEventListener('submit',e=>{if(e.target.id==='rename-form'){e.preventDefault();state.label=$('#label-input').value.trim().slice(0,32)||'Your label';persist();closeModal();render();}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
persist();render();
